contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(msg.value >= amount, "insufficient value");
        require(address(this).balance >= amount, "insufficient balance");

        address owner = c.owner();
        uint ownerBefore = owner.balance;
        uint cBefore = address(c).balance;

        uint cAfter;
        uint ownerAfter;
        bool reverted;

        try c.go{value: amount}() {
            reverted = false;
            cAfter = address(c).balance;
            ownerAfter = owner.balance;
        } catch {
            reverted = true;
            cAfter = address(c).balance;
            ownerAfter = owner.balance;
        }

        require(!reverted);

        // c and owner cannot gain more than the amount sent, since the target
        // can return at most what was forwarded to it; hence cAfter + ownerAfter
        // cannot exceed cBefore + ownerBefore + amount.
        assert(cAfter + ownerAfter <= cBefore + ownerBefore + amount);
    }

    receive() external payable {}
}

